package com.hmdp.ai.api.mcp;import com.hmdp.ai.api.security.RequireAiPermission;import com.hmdp.ai.application.dto.mcp.*;import com.hmdp.ai.application.mcp.McpApplicationService;import com.hmdp.ai.domain.security.AiPermission;import org.springframework.web.bind.annotation.*;import javax.validation.Valid;import java.util.List;
@RestController @RequestMapping("/api/v1/mcp-servers") @RequireAiPermission(AiPermission.MCP_MANAGE) public class McpController {private final McpApplicationService service;public McpController(McpApplicationService service){this.service=service;}@PostMapping public McpServerResponse create(@Valid @RequestBody CreateMcpServerRequest request){return service.create(request);}@GetMapping public List<McpServerResponse>list(){return service.list();}@PostMapping("/{id}/health-check")public McpHealthResponse health(@PathVariable String id){return service.health(id);}@PostMapping("/{id}/sync-tools")public McpSyncResponse sync(@PathVariable String id){return service.sync(id);}}
